), upd as (
  update toko t set skor=v.skor, prioritas=v.prioritas,
    catatan = case when t.catatan is null then v.catatan
                   when t.catatan ~ '^Prioritas [ABC] · skor' then v.catatan || case when position(chr(10) in t.catatan) > 0 then substring(t.catatan from position(chr(10) in t.catatan)) else '' end
                   else v.catatan || chr(10) || t.catatan end,
    alamat=coalesce(t.alamat,v.alamat), no_hp=coalesce(t.no_hp,v.no_hp), media_sosial=coalesce(t.media_sosial,v.media_sosial),
    daerah=coalesce(t.daerah,v.daerah), updated_at=now()
  from v where lower(trim(t.nama))=lower(trim(v.nama)) returning t.id
), ins as (
  insert into toko (nama,alamat,no_hp,media_sosial,daerah,catatan,skor,prioritas,status_approach,updated_at)
  select v.nama,v.alamat,v.no_hp,v.media_sosial,v.daerah,v.catatan,v.skor,v.prioritas,'belum',now() from v
  where not exists (select 1 from toko t where lower(trim(t.nama))=lower(trim(v.nama))) returning id
) select (select count(*) from upd) updated, (select count(*) from ins) inserted;
